import { MeshStandardNodeMaterial } from 'three/webgpu';
import { vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, MeshStandardMaterial, PointLight } = ctx.THREE;

  const group = new Group();

  // Draw from config visual specification
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 1. STAGE: Build the machined stat card backdrop
  // Card base dimensions to fit the hub frame proportions nicely
  const cardWidth = 2.4;
  const cardHeight = 1.6;
  const cardDepth = 0.08;

  const cardGeo = new BoxGeometry(cardWidth, cardHeight, cardDepth);

  // Custom TSL-based material representing "machined surface" with accent glowing rim
  const cardMat = new MeshStandardNodeMaterial({
    color: colors.surface,
    roughness: 0.6,
    metalness: 0.5,
    transparent: true
  });

  // Simple procedural edge glow
  const localPos = cardMat.positionLocal ?? vec3(0.0);
  cardMat.colorNode = mix(
    vec3(colors.surface),
    vec3(colors.accent),
    glowingRim(localPos, cardWidth, cardHeight)
  );

  function glowingRim(pos, w, h) {
    // Subtle glow on edges
    const xEdge = Math.abs(pos.x).sub(w * 0.47).step(0.0);
    const yEdge = Math.abs(pos.y).sub(h * 0.47).step(0.0);
    return xEdge.add(yEdge).clamp(0.0, 1.0);
  }

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.castShadow = true;
  cardMesh.receiveShadow = true;
  group.add(cardMesh);

  // Core accent light mounted on the card
  const statLight = new PointLight(colors.accent, 1.2, 3);
  statLight.position.set(0, 0, 0.4);
  group.add(statLight);

  // 2. HERO: GLB Mesh representation (Gear A)
  let loadedMesh = null;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const scene = gltf.scene;
      scene.scale.set(0.45, 0.45, 0.45);
      scene.position.set(-0.65, 0, 0.1);

      // Give the gear a beautiful machined styling
      scene.traverse((node) => {
        if (node.isMesh) {
          node.material = new MeshStandardMaterial({
            color: colors.paper,
            roughness: 0.25,
            metalness: 0.9,
            flatShading: true
          });
          node.castShadow = true;
        }
      });

      loadedMesh = scene;
      group.add(scene);

      // Idle Rotation animation
      gsap.to(scene.rotation, {
        z: Math.PI * 2,
        duration: 12,
        repeat: -1,
        ease: 'none'
      });
    }).catch(err => {
      console.warn('Failed loading gear mesh:', err);
    });
  }

  // 3. TYPOGRAPHY: Value & Label
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const statValueText = textItems.find(i => i.role === 'value')?.text ?? '98.4%';
  const statLabelText = textItems.find(i => i.role === 'label')?.text ?? 'PRECISION';

  const valueNode = ctx.fontAtlas.createText(statValueText, {
    fontSize: 42,
    color: colors.paper,
    align: 'left'
  });
  valueNode.position.set(0.1, 0.15, 0.05);
  group.add(valueNode);

  const labelNode = ctx.fontAtlas.createText(statLabelText, {
    fontSize: 14,
    color: colors.accent,
    align: 'left',
    letterSpacingPx: 3
  });
  labelNode.position.set(0.1, -0.25, 0.05);
  group.add(labelNode);

  // 4. INTERACTIVE BEHAVIORS (Hover lift, press Click)
  const hoverTimeline = gsap.timeline({ paused: true });
  // Subtle lift and rotation
  hoverTimeline.to(group.position, {
    z: 0.15,
    duration: 0.3,
    ease: 'power2.out'
  });
  hoverTimeline.to(group.rotation, {
    x: 0.05,
    y: -0.05,
    duration: 0.3,
    ease: 'power2.out'
  }, 0);

  group.userData.handlers = {
    pointerover: () => {
      hoverTimeline.play();
    },
    pointerout: () => {
      hoverTimeline.reverse();
    },
    click: () => {
      gsap.timeline()
        .to(group.scale, { x: 0.96, y: 0.96, z: 0.96, duration: 0.08, ease: 'power2.out' })
        .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.15, ease: 'back.out(2)' });

      ctx.emit('hub-home.select', { id: config.id });
    }
  };

  // 5. CINEMATIC PRIMITIVES
  const primitivesRefs = [];
  const primitivesList = config.cinematicPrimitives ?? [];
  primitivesList.forEach((prim) => {
    if (ctx.primitives[prim.name]) {
      const ref = ctx.primitives[prim.name](group, prim.params);
      if (ref) primitivesRefs.push(ref);
    }
  });

  // 6. CLEANUP
  group.userData.cleanup = () => {
    hoverTimeline.kill();
    primitivesRefs.forEach(ref => {
      if (typeof ref.cleanup === 'function') ref.cleanup();
      if (ref.timeline) ref.timeline.kill();
    });
    cardGeo.dispose();
    cardMat.dispose();
  };

  return group;
}
